// Data model for the comprehension game — fields 5.1/5.2/5.3 structure.
// Requested in _TreninkPorozumeni_Fields123_PROMPTS.md (section "User request") and detailed
// in _TreninkPorozumeni_SPEC.md (sections "Fields" and "Examples").
// Wrong-answer spoken explanations requested in _TreninkPorozumeni_Fields123_PROMPTS.md
// (section "User follow-up request — spoken explanation of a wrong picture").
// Asset naming contract per example id:
//   audio:  assets/audio/<id>.mp3
//   images: assets/images/<id>_target.png, <id>_gram.png, <id>_lexa.png, <id>_lexb.png
//   explanation audio: assets/audio/<id>_gram_why.mp3, <id>_lexa_why.mp3, <id>_lexb_why.mp3

import { AudioSource } from 'expo-audio';
import { ImageSourcePropType } from 'react-native';
import { field53Examples } from './items/field53';
import { field54Examples } from './items/field54';
import { field55Examples } from './items/field55';
import { field56Examples } from './items/field56';
import { field57Examples } from './items/field57';
import { field58Examples } from './items/field58';
import { field59Examples } from './items/field59';
import { field510Examples } from './items/field510';
import { field511Examples } from './items/field511';
import { field512Examples } from './items/field512';
import { field513Examples } from './items/field513';
import { field514Examples } from './items/field514';
import { field515Examples } from './items/field515';

// 15 test types 5.1–5.15 ("User request 25" in _TreninkPorozumeni_Fields123_PROMPTS.md);
// names taken from Documentation/doc1 (5.1–5.10) and doc2 (5.11–5.15), shortened to the
// section title without the parenthetical detail. Exception: 5.15 is labelled by its implemented content
// ("Dokonavý a nedokonavý vid", Documentation/TypeScope/5.15_scope.md) instead of the doc2 title
// "Komplexní Časové Relace".
export type FieldId =
  | 'field51' | 'field52' | 'field53' | 'field54' | 'field55'
  | 'field56' | 'field57' | 'field58' | 'field59' | 'field510'
  | 'field511' | 'field512' | 'field513' | 'field514' | 'field515';

export const FIELDS: { id: FieldId; number: string; name: string }[] = [
  { id: 'field51', number: '5.1', name: 'Reverzibilní věty' },
  { id: 'field52', number: '5.2', name: 'Předložkové vazby a prostorové vztahy' },
  { id: 'field53', number: '5.3', name: 'Gramatické číslo' },
  { id: 'field54', number: '5.4', name: 'Slovesný rod' },
  { id: 'field55', number: '5.5', name: 'Negace' },
  { id: 'field56', number: '5.6', name: 'Časování a slovesné časy' },
  { id: 'field57', number: '5.7', name: 'Vztažné a vedlejší věty' },
  { id: 'field58', number: '5.8', name: 'Shoda přísudku s podmětem' },
  { id: 'field59', number: '5.9', name: 'Stupňování přídavných jmen a příslovcí' },
  { id: 'field510', number: '5.10', name: 'Kvantifikátory a logické operátory' },
  { id: 'field511', number: '5.11', name: 'Pronominalizace a anaforické vztahy' },
  { id: 'field512', number: '5.12', name: 'Distributivní kvantifikátory' },
  { id: 'field513', number: '5.13', name: 'Dativní vazby a příjemce děje' },
  { id: 'field514', number: '5.14', name: 'Instrumentální konstrukce' },
  { id: 'field515', number: '5.15', name: 'Dokonavý a nedokonavý vid' },
];

export function fieldLabel(field: FieldId): string {
  const info = FIELDS.find((candidate) => candidate.id === field);
  return info === undefined ? '' : `${info.number} ${info.name}`;
}

// Second, SWAPPED variant of an example ("User request 25" in
// _TreninkPorozumeni_Fields123_PROMPTS.md): a sentence that turns the grammatical
// distractor picture into the target and the old target into the grammatical distractor.
// The lexA/lexB pictures stay (they may hold a doc-defined second grammatical or semantic
// distractor — generic slots), but all three why-wrong texts are re-phrased against the
// new sentence, so each variant carries its own sentence audio + 3 explanations + audios.
// No images here: the swap is expressed purely by the variant number (see src/rounds.ts).
export interface SwappedVariant {
  sentence: string;
  audio: AudioSource; // assets/audio/<id>_v2.mp3
  grammaticalDistractorExplanation: string; // explains the OLD target picture (now wrong)
  grammaticalDistractorExplanationAudio: AudioSource | null; // assets/audio/<id>_v2_gram_why.mp3
  lexicalDistractorAExplanation: string;
  lexicalDistractorAExplanationAudio: AudioSource | null; // assets/audio/<id>_v2_lexa_why.mp3
  lexicalDistractorBExplanation: string;
  lexicalDistractorBExplanationAudio: AudioSource | null; // assets/audio/<id>_v2_lexb_why.mp3
}

export interface ComprehensionExample {
  id: string; // unique slug
  field: FieldId;
  sentence: string; // Czech sentence played/shown
  audio: AudioSource; // assets/audio/<id>.mp3
  targetImage: ImageSourcePropType; // assets/images/<id>_target.png
  grammaticalDistractorImage: ImageSourcePropType; // assets/images/<id>_gram.png
  lexicalDistractorAImage: ImageSourcePropType; // assets/images/<id>_lexa.png
  lexicalDistractorBImage: ImageSourcePropType; // assets/images/<id>_lexb.png
  // Why-it-is-wrong explanations (5-20 words, simple child-friendly Czech), spoken when
  // the given distractor is tapped. If an audio file is ever missing (null), the game
  // falls back to the plain 500 ms red tint.
  grammaticalDistractorExplanation: string;
  grammaticalDistractorExplanationAudio: AudioSource | null; // assets/audio/<id>_gram_why.mp3
  lexicalDistractorAExplanation: string;
  lexicalDistractorAExplanationAudio: AudioSource | null; // assets/audio/<id>_lexa_why.mp3
  lexicalDistractorBExplanation: string;
  lexicalDistractorBExplanationAudio: AudioSource | null; // assets/audio/<id>_lexb_why.mp3
  // Optional variant 2 ("User request 25"); the fields above are variant 1. Items without it
  // always play variant 1.
  swappedVariant?: SwappedVariant;
  // Extra category (_TreninkPorozumeni_Fields123_PROMPTS.md, "User request 27" + "User request 28" Q1–Q5):
  // true = a good item kept outside the regular 1–100 (played via the "Extra" tile, exempt from the ratio
  // rules); absent = a regular item. See src/rounds.ts (EXTRA_PART_OFFSET).
  extra?: true;
}

